import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
class FavoriteAyah { final int surahNumber; final String surahName; final int ayahNumber; final String text; FavoriteAyah({required this.surahNumber, required this.surahName, required this.ayahNumber, required this.text}); String get key => '$surahNumber:$ayahNumber'; Map<String,dynamic> toJson()=>{'surahNumber':surahNumber,'surahName':surahName,'ayahNumber':ayahNumber,'text':text}; factory FavoriteAyah.fromJson(Map<String,dynamic> j)=>FavoriteAyah(surahNumber:j['surahNumber'],surahName:j['surahName'],ayahNumber:j['ayahNumber'],text:j['text']); }
class FavoriteAyahService { static const _key='favorite_ayahs'; static Future<List<FavoriteAyah>> loadFavorites() async { final p=await SharedPreferences.getInstance(); return (p.getStringList(_key)??[]).map((e)=>FavoriteAyah.fromJson(json.decode(e))).toList(); } static Future<void> saveFavorites(List<FavoriteAyah> items) async { final p=await SharedPreferences.getInstance(); await p.setStringList(_key, items.map((e)=>json.encode(e.toJson())).toList()); } static Future<bool> toggle(FavoriteAyah ayah) async { final fav=await loadFavorites(); final i=fav.indexWhere((e)=>e.key==ayah.key); if(i>=0){ fav.removeAt(i); await saveFavorites(fav); return false;} fav.add(ayah); await saveFavorites(fav); return true; } }
